// Generated by forge. The types engine for TypeScript (SPECS §15): a daemon that keeps
// the project's own TypeScript running for one repository and answers the hooks' type
// questions through a FIFO: TypeScript 7 or later through its language server
// (tsc --lsp), TypeScript 5 and 6 through their tsserver. Started by forge_types_up as
//   bun types_typescript.mjs <root> <state-dir>
// It detaches (its own session), then writes "ready <server> <version>" (or
// "failed <reason>") to the FIFO <state-dir>/started, and loads the project's
// tsconfig projects in the background (questions go first). The protocol on
// <state-dir>/in is the Python engine's (types_python.py): "changed<TAB><path>",
// "stop", "restart", or the absolute path of a question directory (req: ast-grep
// matches; reply: the matches whose forge_where holds, "error<TAB>..." lines,
// "unchecked<TAB><rule id><TAB><why>" for a match whose metavariable's type cannot be
// asked, "end").
// A forge_where asks a metavariable's type or the declaration its name refers to
// (SPECS §15.1, §15.6).
// Node-compatible: no Bun-only API.
import { execFileSync, spawn } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = fs.realpathSync(process.argv[2]);
const STATE = process.argv[3];
const IDLE = Number(process.env.FORGE_TYPES_IDLE ?? 1800) * 1000;
const logFile = fs.openSync(path.join(STATE, "log"), "a");
const log = (...a) => fs.writeSync(logFile, `${new Date().toISOString().slice(11, 19)} ${a.join(" ")}\n`);

const uri = (p) => pathToFileURL(fs.existsSync(p) ? fs.realpathSync(p) : p).href;
const pathOf = (u) => (u.startsWith("file://") ? fileURLToPath(u) : u);

/** The LSP position (UTF-16 columns, as JS strings count) of a string index. */
function position(text, index) {
  let line = 0;
  for (let i = text.indexOf("\n"); i >= 0 && i < index; i = text.indexOf("\n", i + 1)) line++;
  return { line, character: index - (text.lastIndexOf("\n", index - 1) + 1) };
}
function indexOf(text, pos) {
  let i = 0;
  for (let l = 0; l < pos.line; l++) i = text.indexOf("\n", i) + 1;
  return i + pos.character;
}

// ---------------------------------------------------------------- the language servers

/**
 * The project's own TypeScript decides the server (§15.2): TypeScript 7 or later, its
 * language server (tsc --lsp); TypeScript 5 and 6, its tsserver. Both are driven
 * through the same small interface: show(file, text), sync(file), changed(file),
 * typeDefinition(file, pos) and definition(file, pos), positions and results as LSP
 * (0-based lines, UTF-16 columns; results [{uri, pos}]).
 */
function projectTypeScript() {
  let pkg;
  try {
    pkg = createRequire(path.join(ROOT, "package.json")).resolve("typescript/package.json");
  } catch {
    throw new Error("the project has no typescript package (node_modules/typescript): install the project's dependencies");
  }
  const version = JSON.parse(fs.readFileSync(pkg, "utf8")).version;
  return { dir: path.dirname(pkg), version, major: Number(version.split(".")[0]) };
}

class Base {
  constructor() {
    this.texts = new Map();
  }
  /** The file as it is on disk; returns its text. */
  sync(file) {
    const text = fs.readFileSync(file, "utf8");
    if (this.texts.get(file) !== text) {
      this.show(file, text);
      this.texts.set(file, text);
    }
    return text;
  }
  exited() {
    log("server exited");
    process.exit(3);
  }
}

/** TypeScript 7: the native compiler's language server, LSP over stdio. */
class Lsp extends Base {
  constructor(ts) {
    super();
    this.proc = spawn(process.execPath, [path.join(ts.dir, "bin", "tsc"), "--lsp", "--stdio"], { cwd: ROOT, stdio: ["pipe", "pipe", logFile] });
    this.proc.on("exit", () => this.exited());
    this.buf = Buffer.alloc(0);
    this.next = 0;
    this.waiting = new Map();
    this.versions = new Map();
    this.proc.stdout.on("data", (d) => this.read(d));
  }
  read(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const sep = this.buf.indexOf("\r\n\r\n");
      if (sep < 0) return;
      const len = Number(/content-length: *(\d+)/i.exec(this.buf.subarray(0, sep).toString())[1]);
      if (this.buf.length < sep + 4 + len) return;
      const msg = JSON.parse(this.buf.subarray(sep + 4, sep + 4 + len).toString());
      this.buf = this.buf.subarray(sep + 4 + len);
      if (msg.method && msg.id !== undefined) {
        // a request from the server (configuration, registrations): defaults, but for the
        // inlay hints of parameter types (typeOfIntersection below)
        const items = msg.params?.items;
        const config = (item) => (item.section === "js/ts" || item.section === "typescript" ? { inlayHints: { parameterTypes: { enabled: true } } } : null);
        this.send({ jsonrpc: "2.0", id: msg.id, result: items ? items.map(config) : null });
      } else if (msg.id !== undefined) {
        this.waiting.get(msg.id)?.(msg.result);
        this.waiting.delete(msg.id);
      }
    }
  }
  send(msg) {
    const body = Buffer.from(JSON.stringify(msg));
    this.proc.stdin.write(Buffer.concat([Buffer.from(`Content-Length: ${body.length}\r\n\r\n`), body]));
  }
  request(method, params) {
    const id = ++this.next;
    return new Promise((resolve) => {
      this.waiting.set(id, resolve);
      this.send({ jsonrpc: "2.0", id, method, params });
    });
  }
  notify(method, params) {
    this.send({ jsonrpc: "2.0", method, params });
  }
  async start() {
    const info = await this.request("initialize", {
      processId: process.pid,
      rootUri: uri(ROOT),
      workspaceFolders: [{ uri: uri(ROOT), name: "root" }],
      capabilities: {
        general: { positionEncodings: ["utf-16"] },
        textDocument: { typeDefinition: { linkSupport: true }, definition: { linkSupport: true }, inlayHint: {}, diagnostic: {} },
        workspace: { configuration: true, workspaceFolders: true },
      },
    });
    this.notify("initialized", {});
    return `${info?.serverInfo?.name ?? "tsc"} ${info?.serverInfo?.version ?? ""}`.trim();
  }
  show(file, text) {
    const u = uri(file);
    const v = (this.versions.get(u) ?? 0) + 1;
    this.versions.set(u, v);
    if (v === 1) this.notify("textDocument/didOpen", { textDocument: { uri: u, languageId: languageId(file), version: v, text } });
    else this.notify("textDocument/didChange", { textDocument: { uri: u, version: v }, contentChanges: [{ text }] });
  }
  changed(file) {
    if (this.versions.has(uri(file))) {
      if (fs.existsSync(file)) this.sync(file);
      return;
    }
    this.notify("workspace/didChangeWatchedFiles", { changes: [{ uri: uri(file), type: fs.existsSync(file) ? 2 : 3 }] });
  }
  async locations(method, file, pos) {
    const r = await this.request(`textDocument/${method}`, { textDocument: { uri: uri(file) }, position: pos });
    return asArray(r).map((l) => ({ uri: l.targetUri ?? l.uri, pos: (l.targetSelectionRange ?? l.targetRange ?? l.range).start }));
  }
  typeDefinition(file, pos) {
    return this.locations("typeDefinition", file, pos);
  }
  definition(file, pos) {
    return this.locations("definition", file, pos);
  }
  /** The positions of the file's syntax errors (TypeScript's diagnostics 1000-1999: the parser's and grammar errors). */
  async syntaxErrors(file) {
    const r = await this.request("textDocument/diagnostic", { textDocument: { uri: uri(file) } });
    return (r?.items ?? []).filter((d) => d.code >= 1000 && d.code < 2000).map((d) => d.range.start);
  }
  /** The inlay hints from <start> to <end>: [{pos, parts: [{text, uri, pos}]}] (uri and pos when the part names a declaration). */
  async inlayHints(file, start, end) {
    const r = await this.request("textDocument/inlayHint", { textDocument: { uri: uri(file) }, range: { start, end } });
    return asArray(r).map((h) => ({
      pos: h.position,
      parts: (Array.isArray(h.label) ? h.label : [{ value: h.label }]).map((p) => ({ text: p.value, uri: p.location?.uri, pos: p.location?.range.start })),
    }));
  }
}

/** TypeScript 5 and 6: the project's tsserver, its own protocol over stdio (1-based lines and offsets). */
class TsServer extends Base {
  constructor(ts) {
    super();
    this.version = ts.version;
    this.proc = spawn(process.execPath, [path.join(ts.dir, "lib", "tsserver.js"), "--disableAutomaticTypingAcquisition", "--suppressDiagnosticEvents"], {
      cwd: ROOT,
      stdio: ["pipe", "pipe", logFile],
    });
    this.proc.on("exit", () => this.exited());
    this.buf = Buffer.alloc(0);
    this.seq = 0;
    this.waiting = new Map();
    this.open = new Set();
    this.shown = new Map();
    this.proc.stdout.on("data", (d) => this.read(d));
  }
  read(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const sep = this.buf.indexOf("\r\n\r\n");
      if (sep < 0) return;
      const len = Number(/content-length: *(\d+)/i.exec(this.buf.subarray(0, sep).toString())[1]);
      if (this.buf.length < sep + 4 + len) return;
      const msg = JSON.parse(this.buf.subarray(sep + 4, sep + 4 + len).toString());
      this.buf = this.buf.subarray(sep + 4 + len);
      if (msg.type === "response") {
        this.waiting.get(msg.request_seq)?.(msg.success ? msg.body : undefined);
        this.waiting.delete(msg.request_seq);
      }
    }
  }
  /** A command; with an answer, a promise of its body. */
  command(command, args, answer = true) {
    const seq = ++this.seq;
    this.proc.stdin.write(`${JSON.stringify({ seq, type: "request", command, arguments: args })}\n`);
    if (!answer) return undefined;
    return new Promise((resolve) => this.waiting.set(seq, resolve));
  }
  async start() {
    // inlay hints of parameter types, with the declarations they name (typeOfIntersection below)
    await this.command("configure", { preferences: { includeInlayFunctionParameterTypeHints: true, interactiveInlayHints: true }, hostInfo: "forge" });
    return `tsserver ${this.version}`;
  }
  show(file, text) {
    if (!this.open.has(file)) {
      this.command("open", { file, fileContent: text, scriptKindName: scriptKind(file), projectRootPath: ROOT }, false);
      this.open.add(file);
    } else {
      // only the span that differs (common prefix and suffix kept): tsserver reparses less
      const old = this.shown.get(file);
      let a = 0;
      while (a < old.length && a < text.length && old[a] === text[a]) a++;
      let b = 0;
      while (b < old.length - a && b < text.length - a && old[old.length - 1 - b] === text[text.length - 1 - b]) b++;
      const at = (i) => {
        const p = position(old, i);
        return { line: p.line + 1, offset: p.character + 1 };
      };
      const change = { start: at(a), end: at(old.length - b), newText: text.slice(a, text.length - b) };
      this.command("updateOpen", { changedFiles: [{ fileName: file, textChanges: [change] }] }, false);
    }
    this.shown.set(file, text);
  }
  changed(file) {
    if (this.open.has(file)) {
      if (fs.existsSync(file)) this.sync(file);
      return;
    }
    // a file the server reads from disk: opening and closing it makes it read it again
    if (fs.existsSync(file)) {
      this.command("open", { file, projectRootPath: ROOT }, false);
      this.command("close", { file }, false);
    }
  }
  async locations(command, file, pos) {
    const body = await this.command(command, { file, line: pos.line + 1, offset: pos.character + 1 });
    return asArray(body).map((s) => ({ uri: pathToFileURL(s.file).href, pos: { line: s.start.line - 1, character: s.start.offset - 1 } }));
  }
  typeDefinition(file, pos) {
    return this.locations("typeDefinition", file, pos);
  }
  definition(file, pos) {
    return this.locations("definition", file, pos);
  }
  async syntaxErrors(file) {
    const body = await this.command("syntacticDiagnosticsSync", { file });
    return asArray(body).map((d) => ({ line: d.start.line - 1, character: d.start.offset - 1 }));
  }
  async inlayHints(file, start, end) {
    const text = this.shown.get(file);
    const offset = (p) => indexOf(text, p);
    const body = await this.command("provideInlayHints", { file, start: offset(start), length: offset(end) - offset(start) });
    const lsp = (p) => ({ line: p.line - 1, character: p.offset - 1 });
    return asArray(body).map((h) => ({
      pos: lsp(h.position),
      parts: (h.displayParts ?? [{ text: h.text }]).map((p) => ({ text: p.text, uri: p.span ? pathToFileURL(p.span.file).href : undefined, pos: p.span ? lsp(p.span.start) : undefined })),
    }));
  }
}

const languageId = (file) =>
  /\.[cm]?tsx?$/.test(file) ? (file.endsWith("x") ? "typescriptreact" : "typescript") : file.endsWith("x") ? "javascriptreact" : "javascript";
const scriptKind = (file) => ({ typescript: "TS", typescriptreact: "TSX", javascript: "JS", javascriptreact: "JSX" })[languageId(file)];

// ---------------------------------------------------------------- declarations

/**
 * [package, module] of a declaration file: the npm package of the innermost
 * node_modules directory (@types/x counts as x, @types/a__b as @a/b) and the file's
 * path in it without its extension; TypeScript's own lib files (lib.*.d.ts) are
 * package "typescript"; [null, path] for the project's own files.
 */
function declaredIn(file) {
  const p = file.split(path.sep).join("/");
  const i = p.lastIndexOf("/node_modules/");
  const strip = (s) => s.replace(/(\.d)?\.[cm]?[jt]sx?$/, "");
  if (i < 0) {
    const real = fs.existsSync(file) ? fs.realpathSync(file) : file;
    return real.startsWith(ROOT + "/") ? [null, strip(real.slice(ROOT.length + 1))] : [null, null];
  }
  // TypeScript's own lib files (shipped in typescript or its native @typescript/* package)
  const lib = /\/node_modules\/(typescript|@typescript\/[^/]+)\/lib\/(lib\.[^/]*)\.d\.ts$/.exec(p);
  if (lib) return ["typescript", `typescript/lib/${lib[2]}`];
  const segs = p.slice(i + "/node_modules/".length).split("/");
  let pkg = segs[0].startsWith("@") ? `${segs[0]}/${segs[1]}` : segs[0];
  const rest = segs.slice(pkg.split("/").length).join("/");
  if (pkg.startsWith("@types/")) {
    const t = pkg.slice(7);
    pkg = t.includes("__") ? `@${t.replace("__", "/")}` : t;
  }
  return [pkg, `${pkg}/${strip(rest)}`];
}

const WORD = /[A-Za-z_$][\w$]*/y;
const KEYWORDS = new Set(["export", "declare", "default", "abstract", "async", "class", "interface", "type", "enum", "const", "let", "var", "function", "namespace", "module"]);

function readText(file) {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return undefined;
  }
}

/** The index of the first character at or after <i> that is not whitespace or a comment. */
function skipTrivia(text, i) {
  for (;;) {
    while (i < text.length && /\s/.test(text[i])) i++;
    if (text.startsWith("//", i)) {
      const n = text.indexOf("\n", i);
      i = n < 0 ? text.length : n + 1;
    } else if (text.startsWith("/*", i)) {
      const n = text.indexOf("*/", i + 2);
      i = n < 0 ? text.length : n + 2;
    } else return i;
  }
}

/** The index just past the string literal starting at <i> (its quote). */
function skipString(text, i) {
  const q = text[i];
  for (let j = i + 1; j < text.length; j++) {
    if (text[j] === "\\") j++;
    else if (text[j] === q) return j + 1;
  }
  return text.length;
}

/**
 * The name of the type alias whose body holds <index>, the start of an anonymous type
 * (an object type literal, a function or tuple type): `type UseFormWatch<T> = { … }`
 * gives UseFormWatch. The servers point the type definition of such a type at the
 * literal, which has no name of its own. Undefined when no alias declares it (an inline
 * type annotation).
 */
function enclosingAlias(text, index) {
  const heads = [...text.slice(0, index).matchAll(/\btype\s+([A-Za-z_$][\w$]*)/g)];
  for (let h = heads.length - 1; h >= 0; h--) {
    const head = heads[h];
    // past the name and its type parameters (balanced <>, where => is not a closing >)
    let i = skipTrivia(text, head.index + head[0].length);
    if (text[i] === "<") {
      let depth = 0;
      for (; i < index; i++) {
        if (text[i] === "=" && text[i + 1] === ">") i++;
        else if (text[i] === "<") depth++;
        else if (text[i] === ">" && --depth === 0) break;
      }
      i = skipTrivia(text, i + 1);
    }
    if (text[i] !== "=" || text[i + 1] === ">" || i >= index) continue;
    // the alias's statement goes on to a ; at depth 0 (or the end of the enclosing block)
    let depth = 0;
    let ended = false;
    for (let j = i + 1; j < index && !ended; ) {
      const k = skipTrivia(text, j);
      if (k !== j) {
        j = k;
        continue;
      }
      const c = text[j];
      if (c === '"' || c === "'" || c === "`") j = skipString(text, j);
      else {
        if ("([{".includes(c)) depth++;
        else if (")]}".includes(c)) ended = --depth < 0;
        else if (c === ";" && depth === 0) ended = true;
        j++;
      }
    }
    if (!ended) return head[1];
  }
  return undefined;
}

/**
 * The declared name at <index> (keywords and comments skipped): { name, end, alias }, with
 * end where a class or interface header's heritage clauses start (or a type alias's type
 * parameters), alias true for a type alias; an anonymous type gets the name of the alias
 * declaring it, and no heritage (end undefined).
 */
function nameAt(text, index) {
  let alias = false;
  for (let i = skipTrivia(text, index); i < text.length; i = skipTrivia(text, i)) {
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      const name = enclosingAlias(text, i);
      return name ? { name, end: undefined } : undefined;
    }
    // a type alias: `type` before its name (the server points at the name, or at the statement)
    if (!KEYWORDS.has(m[0])) return { name: m[0], end: i + m[0].length, alias: alias || /\btype\s+$/.test(text.slice(Math.max(0, i - 64), i)) };
    alias = m[0] === "type";
    i += m[0].length;
  }
  return undefined;
}

// words of a type that name no declaration
const TYPE_WORDS = new Set([
  "string", "number", "boolean", "bigint", "symbol", "object", "unknown", "any", "never", "void", "null", "undefined", "true", "false",
  "this", "readonly", "unique", "asserts", "is", "infer", "new", "abstract",
]);

/** The index just past the group (<>, (), [], {}) opening at <i>; => is not a closing >. */
function skipGroup(text, i, to = text.length) {
  let depth = 0;
  for (let j = i; j < to; ) {
    const k = skipTrivia(text, j);
    if (k !== j) {
      j = k;
      continue;
    }
    const c = text[j];
    if (c === '"' || c === "'" || c === "`") {
      j = skipString(text, j);
      continue;
    }
    if (c === "=" && text[j + 1] === ">") {
      j += 2;
      continue;
    }
    if ("<([{".includes(c)) depth++;
    else if (">)]}".includes(c) && --depth === 0) return j + 1;
    j++;
  }
  return to;
}

/**
 * The positions of the names a type expression (text from <from> to <to>) is made of at
 * its top level: the type it names, or each member of a union or intersection, through
 * grouping parentheses (the last segment of a qualified name). Type arguments, object
 * and tuple literals, function types, indexed accesses and arrays (`T[]`), `typeof` and
 * `keyof` operands and <skip> (type parameters) name none; a conditional type names none
 * (it is one of its branches, decided by its arguments).
 */
function topLevelNames(text, from, to, skip = new Set()) {
  const out = [];
  let i = from;
  let operand = false; // the next name is an operand of typeof / keyof
  while (i < to) {
    i = skipTrivia(text, i);
    if (i >= to) break;
    const c = text[i];
    if (c === '"' || c === "'" || c === "`") {
      i = skipString(text, i);
      continue;
    }
    if (c === "?") return []; // a conditional type
    if (c === "=" && text[i + 1] === ">") break; // a function type's result
    if (c === "(") {
      const end = skipGroup(text, i, to);
      if (text.startsWith("=>", skipTrivia(text, end))) break; // a function type
      i++; // grouping: transparent
      continue;
    }
    if (c === ")") {
      i++;
      continue;
    }
    if ("<[{".includes(c)) {
      i = skipGroup(text, i, to);
      continue;
    }
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      i++;
      continue;
    }
    if (m[0] === "extends") return []; // a conditional type
    // a qualified name: its last segment (import("m").X: X)
    let last = i;
    let j = i + m[0].length;
    if (m[0] === "import" && text[skipTrivia(text, j)] === "(") {
      j = skipGroup(text, skipTrivia(text, j), to);
      last = -1;
    }
    while (text[skipTrivia(text, j)] === "." && /[A-Za-z_$]/.test(text[skipTrivia(text, skipTrivia(text, j) + 1)] ?? "")) {
      const k = skipTrivia(text, skipTrivia(text, j) + 1);
      WORD.lastIndex = k;
      const n = WORD.exec(text);
      last = k;
      j = k + n[0].length;
    }
    if (m[0] === "typeof" || m[0] === "keyof") {
      operand = true;
      i = j;
      continue;
    }
    let after = skipTrivia(text, j);
    if (text[after] === "<") after = skipTrivia(text, skipGroup(text, after, to));
    const indexed = text[after] === "[";
    const qualified = last !== i;
    if (last >= 0 && !operand && !indexed && (qualified || (!TYPE_WORDS.has(m[0]) && !skip.has(m[0])))) out.push(last);
    operand = false;
    i = after;
  }
  return out;
}

/**
 * The positions of the names a type alias's body is made of at its top level
 * (topLevelNames): from the end of its name, past its type parameters, to the end of its
 * statement (a ; or a line that does not go on with & or |).
 */
function aliasMembers(text, from) {
  let i = skipTrivia(text, from);
  const params = new Set();
  if (text[i] === "<") {
    const end = skipGroup(text, i);
    // each type parameter's name: the first word of each item of the list
    for (let j = skipTrivia(text, i + 1); j < end - 1; ) {
      WORD.lastIndex = j;
      const m = WORD.exec(text);
      if (m) params.add(m[0]);
      // on to the next item: past groups, to the next , of the list
      while (j < end - 1 && text[j] !== ",") j = "<([{".includes(text[j]) ? skipGroup(text, j, end) : text[j] === '"' || text[j] === "'" ? skipString(text, j) : j + 1;
      j = skipTrivia(text, j + 1);
    }
    i = skipTrivia(text, end);
  }
  if (text[i] !== "=" || text[i + 1] === ">") return [];
  // the end of the statement
  let to = text.length;
  for (let j = i + 1; j < text.length; ) {
    const k = skipTrivia(text, j);
    if (k !== j) {
      const gap = text.slice(j, k);
      const before = text.slice(i + 1, j).trimEnd();
      if (gap.includes("\n") && before && !/[&|=,<(]$/.test(before) && !/^[&|]/.test(text.slice(k))) {
        to = j;
        break;
      }
      j = k;
      continue;
    }
    const c = text[j];
    if (c === '"' || c === "'" || c === "`") j = skipString(text, j);
    else if ("<([{".includes(c)) j = skipGroup(text, j);
    else if (c === ";" || ")]}".includes(c)) {
      to = j;
      break;
    } else j++;
  }
  return topLevelNames(text, i + 1, to, params);
}

/**
 * The positions of the names a class or interface header extends or implements
 * (at depth 0 of <>, (), []; the last segment of a qualified name), from the end of
 * its name to its body.
 */
function heritage(text, from) {
  const out = [];
  let depth = 0;
  let list = false;
  for (let i = from; i < text.length; ) {
    const c = text[i];
    if (c === "/" && text[i + 1] === "/") {
      i = text.indexOf("\n", i);
      if (i < 0) break;
      continue;
    }
    if (c === "/" && text[i + 1] === "*") {
      i = text.indexOf("*/", i) + 2;
      continue;
    }
    if (c === "=" && text[i + 1] === ">") {
      i += 2;
      continue;
    }
    if ("<([{".includes(c)) {
      if (c === "{" && depth === 0) break;
      depth++;
      i++;
      continue;
    }
    if (">)]}".includes(c)) {
      depth--;
      i++;
      continue;
    }
    if ((c === ";" || c === "=") && depth === 0) break;
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      i++;
      continue;
    }
    if (depth === 0 && (m[0] === "extends" || m[0] === "implements")) list = true;
    else if (depth === 0 && list) {
      let last = i;
      let j = i + m[0].length;
      while (text[j] === "." && /[A-Za-z_$]/.test(text[j + 1] ?? "")) {
        WORD.lastIndex = j + 1;
        const n = WORD.exec(text);
        last = j + 1;
        j = j + 1 + n[0].length;
      }
      out.push(last);
      i = j;
      continue;
    }
    i += m[0].length;
  }
  return out;
}

/**
 * Whether <index> is in the clause of an import declaration (`import { a, b as c }`,
 * `import d, * as ns`): where a server's definition stops when it cannot resolve the
 * module. The clause holds no string, parenthesis, `=` or `;`.
 */
function inImport(text, index) {
  for (let i = text.lastIndexOf("import", index); i >= 0; i = text.lastIndexOf("import", i - 1)) {
    if (/[\w$]/.test(text[i - 1] ?? "") || !/\s/.test(text[i + 6] ?? "")) continue;
    if (/[;'"`()=]/.test(text.slice(i + 6, index))) return false;
    return /(^|[;}\n])\s*$/.test(text.slice(Math.max(0, i - 200), i));
  }
  return false;
}

/**
 * The text with the expressions of <ranges> (string indices) for which <active>(n) holds
 * each bound to a fresh parameter, ((__forge_t<n> = (<expr>)) => __forge_t<n>)():
 * {overlay, events (the inserts: [offset, kind, size, n, text]), anchors (n -> [start,
 * end] of the parameter's name), refs (n -> where the arrow uses it)}.
 */
function bindings(text, ranges, active) {
  // inserts: at each start the opening, at each end the closing; at the same offset,
  // closings first (inner first), then openings (outer first)
  const events = [];
  ranges.forEach(([s, e], n) => {
    if (!active(n)) return;
    events.push([s, 1, -(e - s), n, `((__forge_t${n} = (`]);
    events.push([e, 0, e - s, n, `)) => __forge_t${n})()`]);
  });
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2] || a[3] - b[3]);
  let overlay = "";
  let last = 0;
  const anchors = [];
  const refs = [];
  for (const [off, kind, , n, piece] of events) {
    overlay += text.slice(last, off);
    last = off;
    if (kind === 1) anchors[n] = [overlay.length + 2, overlay.length + 2 + `__forge_t${n}`.length]; // the parameter's name
    else refs[n] = overlay.length + 6; // the arrow's use of it
    overlay += piece;
  }
  overlay += text.slice(last);
  return { overlay, events, anchors, refs };
}

class Types {
  constructor(server) {
    this.server = server;
    this.cache = new Map();
  }
  /**
   * The declarations [package, module, name] of the type declared at loc and of its
   * supertypes, transitively: the classes and interfaces it extends or implements and,
   * for a type alias, the types its body is made of (the one it renames, or the members
   * of its union or intersection).
   */
  async hierarchy(loc) {
    const key = `${loc.uri}:${loc.pos.line}:${loc.pos.character}`;
    if (this.cache.has(key)) return this.cache.get(key);
    const out = new Map();
    const seen = new Set();
    const todo = [loc];
    while (todo.length && seen.size < 64) {
      const l = todo.pop();
      const k = `${l.uri}:${l.pos.line}:${l.pos.character}`;
      if (seen.has(k)) continue;
      seen.add(k);
      const file = pathOf(l.uri);
      const [pkg, mod] = declaredIn(file);
      const text = readText(file);
      if (text === undefined) continue;
      const at = nameAt(text, indexOf(text, l.pos));
      if (!at) continue;
      out.set(`${pkg}\0${mod}\0${at.name}`, [pkg, mod, at.name]);
      const bases = at.end === undefined ? [] : at.alias ? aliasMembers(text, at.end) : heritage(text, at.end);
      const defs = await Promise.all(
        bases.map((b) => this.server.definition(file, position(text, b))),
      );
      for (const d of defs) todo.push(...d);
    }
    const value = [...out.values()];
    if (!pathOf(loc.uri).startsWith(ROOT + "/") || loc.uri.includes("/node_modules/")) this.cache.set(key, value);
    return value;
  }
  /**
   * wanted: [[match index, variable, start byte, end byte]]. Returns a Map
   * "index\0variable" -> declarations, from the type the server infers for each
   * expression: the file is shown to the server with each expression wrapped as
   * ((__forge_t<i> = (<expr>)) => __forge_t<i>)(), in memory only, and the type
   * definition of that parameter is asked. A type without a declaration of its own (an
   * intersection, an alias of one) gets none: then the parameter's inlay hint, the type
   * as the checker prints it with the declaration each name refers to, gives the
   * declarations of its top-level members (typeOfIntersection). named: the same for the
   * declarations names refer to (declared below), asked on that same version of the file.
   */
  async check(file, wanted, named = []) {
    const text = fs.readFileSync(file, "utf8");
    const raw = Buffer.from(text, "utf8");
    if (!wanted.length) {
      this.server.sync(file);
      return this.declared(file, text, raw, named, text, []);
    }
    const ranges = [];
    const slot = wanted.map(([, , s, e]) => {
      const r = [raw.subarray(0, s).toString("utf8").length, raw.subarray(0, e).toString("utf8").length];
      let i = ranges.findIndex(([a, b]) => a === r[0] && b === r[1]);
      if (i < 0) i = ranges.push(r) - 1;
      return i;
    });
    // code that is not an expression (a parameter's or a property's name) makes the file
    // unparsable once bound: such a binding is dropped and the others asked again, so the
    // rest of the file is still answered; its matches are not checked
    const unchecked = new Set();
    let shown;
    let results;
    for (;;) {
      shown = bindings(text, ranges, (n) => !unchecked.has(n));
      // the server keeps this version until the file changes: the wrapping binds no name, so
      // what other files see of this one is unchanged (one program update per question)
      this.server.show(file, shown.overlay);
      this.server.texts.set(file, shown.overlay);
      const { overlay, anchors, refs } = shown;
      results = await Promise.all(ranges.map((_, n) => (unchecked.has(n) ? [] : this.server.typeDefinition(file, position(overlay, anchors[n][0] + 1)))));
      const unknown = [];
      for (const [n, r] of results.entries()) {
        if (r.length || unchecked.has(n)) continue;
        results[n] = await this.typeOfIntersection(file, overlay, anchors[n]);
        if (!results[n].length) unknown.push(n);
      }
      // a binding the parser rejects: a syntax error in the code it inserts
      const errors = unknown.length ? (await this.server.syntaxErrors(file)).map((p) => indexOf(overlay, p)) : [];
      const inserted = (n) => [
        [anchors[n][0] - 2, anchors[n][1] + 4], // ((__forge_t<n> = (
        [refs[n] - 6, refs[n] + `__forge_t${n})()`.length], // )) => __forge_t<n>)()
      ];
      const unbound = unknown.filter((n) => errors.some((i) => inserted(n).some(([a, b]) => a <= i && i < b)));
      if (!unbound.length) break;
      // the first one: those after it may only be broken by it
      unchecked.add(unbound.reduce((a, b) => (ranges[b][0] < ranges[a][0] ? b : a)));
    }
    const perRange = [];
    for (const [n, r] of results.entries()) {
      const decls = [];
      for (const l of r) decls.push(...(await this.hierarchy(l)));
      // any and unknown have no declaration: the checker does not know the type
      perRange.push({ decls, unknown: decls.length === 0, unchecked: unchecked.has(n) });
    }
    const found = await this.declared(file, text, raw, named, shown.overlay, shown.events);
    for (const [n, w] of wanted.entries()) found.set(`${w[0]}\0${w[1]}`, perRange[slot[n]]);
    return found;
  }
  /**
   * The declarations of the top-level members of the type of the parameter whose name is
   * at [start, end) in <overlay>: its inlay hint is the type as the checker prints it
   * (an alias's name when it has one), each name in it with the declaration it refers to;
   * the names at the top level of that text (topLevelNames) give the locations. None when
   * the server gives no hint (any, unknown, an error type print nothing that names a
   * declaration).
   */
  async typeOfIntersection(file, overlay, [start, end]) {
    const at = position(overlay, end);
    const hints = await this.server.inlayHints(file, position(overlay, start), at);
    const hint = hints.find((h) => h.pos.line === at.line && h.pos.character === at.character);
    if (!hint) return [];
    // the printed type as one text, with where each part naming a declaration starts
    let text = "";
    const named = new Map();
    for (const p of hint.parts) {
      if (p.uri && p.pos) named.set(text.length, { uri: p.uri, pos: p.pos });
      text += p.text;
    }
    const from = text.indexOf(":") + 1; // the hint is ": <type>"
    return topLevelNames(text, from, text.length).flatMap((i) => (named.has(i) ? [named.get(i)] : []));
  }
  /**
   * Map "index\0variable" -> {decls, unknown} of the names in named: the declarations
   * the server's definition of the expression's last name gives (an import alias or a
   * re-export resolved; overloads and merged declarations each count), asked on the
   * version of the file the server has (<shown>: the text with <events> inserted). An
   * expression that does not end with a name, a name without a definition and one whose
   * definition is an import the server could not resolve are unknown.
   */
  async declared(file, text, raw, named, shown, events) {
    const found = new Map();
    const asked = new Map();
    for (const [n, v, s, e] of named) {
      const expr = raw.subarray(s, e).toString("utf8");
      const m = /[A-Za-z_$][\w$]*$/.exec(expr);
      if (!m || (m.index > 0 && !expr.slice(0, m.index).trimEnd().endsWith("."))) {
        found.set(`${n}\0${v}`, { decls: [], unknown: true });
        continue;
      }
      const at = raw.subarray(0, s).toString("utf8").length + m.index;
      // where the name is in the version shown: past every insert at or before it
      const shift = events.reduce((sum, [off, , , , piece]) => sum + (off <= at ? piece.length : 0), 0);
      if (!asked.has(at)) {
        // a called name (f(…), f<T>(…), f`…`): the servers add the declaration of the signature
        // it is called with after the name's own declarations, when that is another one (a
        // variable holding a function): what it is called with, not what the name refers to
        const after = skipTrivia(shown, at + shift + m[0].length);
        const called = "(<`".includes(shown[after] ?? "");
        asked.set(at, this.server.definition(file, position(shown, at + shift)).then((ls) => (called && ls.length > 1 ? ls.slice(0, -1) : ls)));
      }
      found.set(`${n}\0${v}`, at);
    }
    const answers = new Map();
    for (const [at, locations] of asked) {
      const decls = new Map();
      for (const l of await locations) {
        const f = pathOf(l.uri);
        const body = f === file || (fs.existsSync(f) && fs.realpathSync(f) === fs.realpathSync(file)) ? shown : readText(f);
        if (body === undefined) continue;
        const i = indexOf(body, l.pos);
        if (inImport(body, i)) continue; // the server stopped at an import it could not resolve
        const [pkg, mod] = declaredIn(f);
        const name = nameAt(body, i)?.name ?? null;
        decls.set(`${pkg}\0${mod}\0${name}`, [pkg, mod, name]);
      }
      answers.set(at, { decls: [...decls.values()], unknown: decls.size === 0 });
    }
    for (const [k, v] of found) if (typeof v === "number") found.set(k, answers.get(v));
    return found;
  }
}

const asArray = (r) => (Array.isArray(r) ? r : r ? [r] : []);

// ---------------------------------------------------------------- constraints

const listed = (v) => (v === undefined ? undefined : Array.isArray(v) ? v : [v]);

/**
 * A type spec ({package, module, name, unknown}) holds when one declaration of the type
 * (a union member, or a supertype of one) is declared there with that name; a type the
 * checker does not know (any, unknown) holds only with unknown: match.
 */
function satisfies({ decls, unknown }, spec) {
  if (unknown) return spec.unknown === "match";
  const pkgs = listed(spec.package);
  const mods = listed(spec.module);
  const names = listed(spec.name);
  return decls.some(
    ([pkg, mod, name]) =>
      (!pkgs || pkgs.includes(pkg)) && (!mods || mods.some((m) => mod === m || (mod ?? "").startsWith(`${m}/`))) && (!names || names.includes(name)),
  );
}
// several specs: one of them is enough
const holds = (decls, cond) => (cond.not ? !holds(decls, cond.not) : [cond.type ?? cond.declared].flat().some((spec) => satisfies(decls, spec)));
/** What a condition asks of its metavariable: "type" or "declared". */
const asks = (cond) => (cond.not ? asks(cond.not) : cond.declared ? "declared" : "type");

async function answer(types, matches) {
  const byFile = new Map();
  matches.forEach((m, n) => {
    const where = m.metadata?.forge_where ?? {};
    const single = m.metaVariables?.single ?? {};
    for (const [v, cond] of Object.entries(where)) {
      if (!single[v]) continue;
      const b = single[v].range.byteOffset;
      if (!byFile.has(m.file)) byFile.set(m.file, { type: [], declared: [] });
      byFile.get(m.file)[asks(cond)].push([n, v, b.start, b.end]);
    }
  });
  const found = new Map();
  for (const [f, kinds] of byFile) for (const [k, d] of await types.check(path.join(ROOT, f), kinds.type, kinds.declared)) found.set(k, d);
  // a match with a metavariable whose type cannot be asked is not checked (never passed)
  const unchecked = matches.flatMap((m, n) => Object.keys(m.metadata?.forge_where ?? {}).filter((v) => found.get(`${n}\0${v}`)?.unchecked).map((v) => [n, v]));
  const keep = matches.flatMap((m, n) =>
    !unchecked.some(([u]) => u === n) &&
    Object.entries(m.metadata?.forge_where ?? {}).every(([v, cond]) => !found.has(`${n}\0${v}`) || holds(found.get(`${n}\0${v}`), cond))
      ? [n]
      : [],
  );
  return { keep, unchecked };
}

// ---------------------------------------------------------------- the FIFO loop

/** "unchecked<TAB><rule id><TAB><why>": a match the engine cannot check. */
const uncheckedLine = (m, v) =>
  `unchecked\t${m.ruleId}\t${m.file}:${m.range.start.line + 1}: $${v} is bound to \`${m.metaVariables.single[v].text.split("\n")[0].slice(0, 40)}\`, which is not an expression: its type cannot be asked`;

function reply(dir, lines) {
  let fd;
  try {
    fd = fs.openSync(path.join(dir, "reply"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
  } catch {
    return; // nobody waits for it
  }
  const data = Buffer.from([...lines, "end"].map((l) => `${l}\n`).join(""));
  for (let off = 0; off < data.length; ) {
    try {
      off += fs.writeSync(fd, data, off);
    } catch (e) {
      if (e.code !== "EAGAIN") break;
    }
  }
  fs.closeSync(fd);
}

/** Removes the daemon's files, unless another daemon took the state directory over. */
function cleanup() {
  if (readText(path.join(STATE, "pid"))?.trim() !== String(process.pid)) return;
  for (const n of ["ready", "pid", "in", "loading"]) fs.rmSync(path.join(STATE, n), { force: true });
}

/** Tells the starter (waiting on <state>/started) how the start went. */
function started(line) {
  try {
    const fd = fs.openSync(path.join(STATE, "started"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
    fs.writeSync(fd, `${line}\n`);
    fs.closeSync(fd);
  } catch {
    // nobody waits for it
  }
}

/**
 * One file of each tsconfig project the repository tracks (outside node_modules), so
 * the server loads them before the first question needs them.
 */
function preloadFiles() {
  let files;
  try {
    files = execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard"], { cwd: ROOT, maxBuffer: 1 << 28 }).toString().split("\0");
  } catch {
    return [];
  }
  const sources = files.filter((f) => /\.[cm]?tsx?$/.test(f) && !/\.d\.[cm]?ts$/.test(f) && !f.includes("node_modules/"));
  return files
    .filter((f) => /(^|\/)tsconfig\.json$/.test(f) && !f.includes("node_modules/"))
    .map((t) => {
      const dir = path.dirname(t) === "." ? "" : `${path.dirname(t)}/`;
      return sources.find((s) => s.startsWith(dir));
    })
    .filter((f, i, all) => f && all.indexOf(f) === i)
    .map((f) => path.join(ROOT, f));
}

async function main() {
  // detach: a session of its own, so ending the hook that started it does not end it
  if (!process.env.FORGE_TYPES_DETACHED) {
    spawn(process.execPath, process.argv.slice(1), { detached: true, stdio: "ignore", env: { ...process.env, FORGE_TYPES_DETACHED: "1" } }).unref();
    return;
  }
  fs.writeFileSync(path.join(STATE, "pid"), `${process.pid}\n`);
  const fd = fs.openSync(path.join(STATE, "in"), fs.constants.O_RDWR);
  const ts = projectTypeScript();
  const server = ts.major >= 7 ? new Lsp(ts) : new TsServer(ts);
  const ready = await server.start();
  fs.writeFileSync(path.join(STATE, "ready"), `${ready}\n`);
  log("started", ready, "for", ROOT);
  started(`ready ${ready}`);
  const types = new Types(server);
  // "stop<TAB><dir>": answered in <dir>/reply once the server has exited
  const stop = (why, dir) => {
    log("exiting:", why);
    cleanup();
    server.proc.removeAllListeners("exit");
    const done = () => {
      if (dir) reply(dir, []);
      process.exit(0);
    };
    if (server.proc.exitCode !== null || server.proc.signalCode !== null) done();
    server.proc.once("exit", done);
    setTimeout(() => server.proc.kill("SIGKILL"), 5000).unref();
    server.proc.kill();
  };
  // one job at a time: the FIFO's lines in order, the preload when there is none
  const lines = [];
  const preload = preloadFiles().map((file) => async () => {
    const t = performance.now();
    server.sync(file);
    await server.typeDefinition(file, { line: 0, character: 0 });
    log(`loaded the project of ${path.relative(ROOT, file)} in ${(performance.now() - t).toFixed(0)} ms`);
  });
  // while projects load, "loading" tells the hooks a question may wait for one (§15.3)
  const loading = path.join(STATE, "loading");
  if (preload.length) fs.writeFileSync(loading, `${preload.length}\n`);
  let running = false;
  const pump = () => {
    if (running) return;
    if (!preload.length) fs.rmSync(loading, { force: true });
    const job = lines.length ? lines.shift() : preload.shift();
    if (!job) return;
    running = true;
    Promise.resolve()
      .then(job)
      .catch((e) => log("error", e.stack ?? e))
      .finally(() => {
        running = false;
        pump();
      });
  };
  let idle = setTimeout(() => stop("idle"), IDLE);
  // the state directory was dropped (its FIFO gone or replaced), another daemon took it
  // over (its pid file names that one: a start whose starter was killed can race with the
  // next start, and both open the same FIFO) or the repository is gone: nobody reaches
  // this daemon any more
  const inode = fs.fstatSync(fd).ino;
  setInterval(() => {
    let gone;
    try {
      gone = fs.readFileSync(path.join(STATE, "pid"), "utf8").trim() !== String(process.pid) || fs.statSync(path.join(STATE, "in")).ino !== inode || !fs.existsSync(ROOT);
    } catch {
      gone = true;
    }
    if (gone) {
      log("orphaned, exiting");
      server.proc.removeAllListeners("exit");
      server.proc.kill();
      process.exit(0);
    }
  }, 10_000).unref();
  let buf = "";
  const stream = fs.createReadStream(null, { fd, autoClose: false, encoding: "utf8" });
  stream.on("data", (chunk) => {
    clearTimeout(idle);
    idle = setTimeout(() => stop("idle"), IDLE);
    buf += chunk;
    for (let i; (i = buf.indexOf("\n")) >= 0; ) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      lines.push(() => {
        if (line.startsWith("changed\t")) server.changed(path.join(ROOT, line.slice(8)));
        else if (line === "stop" || line === "restart") stop(`asked to ${line}`);
        else if (line.startsWith("stop\t")) stop("asked to stop", line.slice(5));
        else if (line.startsWith("/")) return question(types, line);
      });
    }
    pump();
  });
  pump();
}

async function question(types, dir) {
  const req = readText(path.join(dir, "req"));
  if (req === undefined) return;
  const matches = [];
  const raw = [];
  const out = [];
  for (const l of req.split("\n")) {
    if (!l) continue;
    try {
      matches.push(JSON.parse(l));
      raw.push(l);
    } catch {
      out.push(`error\tunreadable match: ${l.slice(0, 80)}`);
    }
  }
  const t = performance.now();
  try {
    const { keep, unchecked } = await answer(types, matches);
    for (const n of keep) out.push(raw[n]);
    for (const [n, v] of unchecked) out.push(uncheckedLine(matches[n], v));
  } catch (e) {
    log("error", e.stack ?? e);
    out.push(`error\t${e.message ?? e}`);
  }
  log(`answered ${matches.length} matches in ${(performance.now() - t).toFixed(1)} ms`);
  reply(dir, out);
}

main().catch((e) => {
  log("failed", e.stack ?? e);
  started(`failed ${e.message ?? e}`);
  cleanup();
  process.exit(2);
});
